(()=>{'use strict';const $=id=>document.getElementById(id),api=window.MarketOverlay;let limit=100,paused=false,last=null,signature='',cards=new Map();const money=n=>Number(n).toLocaleString('ru-RU'),serverNames={europe:'Европа',west:'Америка',east:'Азия'};
function paint(state){last=state;const rows=(state.quotes||[]).filter(row=>!state.server||row.server===state.server);$('status').textContent=(state.running?'Сканер включён':'Сканер выключен')+(state.server?' · '+serverNames[state.server]:'');$('prices').textContent=rows.reduce((n,r)=>n+!!r.ask+!!r.bid,0)+' цен';$('orders').textContent=money(state.orders||0)+' ордеров';$('session').textContent='За включение: новых '+(state.session?.added||0)+', обновлений '+(state.session?.updated||0);if(paused)return;
const sorted=rows.slice().sort((a,b)=>Math.max(b.askTime||0,b.bidTime||0)-Math.max(a.askTime||0,a.bidTime||0)).slice(0,limit);const next=limit+'|'+JSON.stringify(sorted);if(next===signature)return;signature=next;const scroll=$('list').scrollTop,fragment=document.createDocumentFragment();for(const row of sorted){const key=[row.server,row.item,row.city,row.quality].join('|');let nodes=cards.get(key);if(!nodes){nodes={card:document.createElement('article'),name:document.createElement('strong'),info:document.createElement('div'),prices:document.createElement('div')};nodes.card.append(nodes.name,nodes.info,nodes.prices);cards.set(key,nodes);}const {card,name,info,prices}=nodes;name.textContent=(window.ALBION_DATA?.names?.[row.item]||row.item)+' · качество '+row.quality;info.textContent=row.city+' · '+new Date(Math.max(row.askTime||0,row.bidTime||0)).toLocaleTimeString('ru-RU');prices.textContent='Предложение: '+(row.ask?money(row.ask):'—')+' · Заявка: '+(row.bid?money(row.bid):'—');fragment.append(card);}const visibleKeys=new Set(sorted.map(row=>[row.server,row.item,row.city,row.quality].join('|')));for(const key of cards.keys())if(!visibleKeys.has(key))cards.delete(key);if(!sorted.length){const empty=document.createElement('p');empty.textContent='Пока нет считанных цен. Просматривайте товары на рынке игры.';fragment.append(empty);}$('list').replaceChildren(fragment);$('list').scrollTop=scroll;$('shown').textContent='Показано '+sorted.length+' из '+rows.length;}
$('more').onclick=()=>{limit+=100;if(last)paint(last);};$('close').onclick=()=>api.command('close');$('pause').onclick=()=>{paused=!paused;$('pause').textContent=paused?'Продолжить список':'Приостановить список';if(!paused&&last)paint(last);};api.onState(paint);api.command('state').then(paint);
})();
